import {createHash} from 'node:crypto';
import {readFile, lstat} from 'node:fs/promises';
import path from 'node:path';
import {asError, CliError} from './errors.ts';
import {assertWritablePath} from './project.ts';

// SHA-256 of the six project skills generated by OpenSpec 1.16.0 for Codex.
const legacyHashes: Record<string, string> = {
  'openspec-apply-change': 'c190210594f5b0c6b76f1b23d8ea261f94987adeed727ac0864b732ef7cdea75',
  'openspec-archive-change': 'c3df5c96f8e829ed16952689de041d215b7d5749b0b261b1531c685d4ee68bed',
  'openspec-explore': '0c97108351cff3bc0b84b53c173cfa6615b5fbcb67742140940bd7f2858e6231',
  'openspec-propose': '3649c686b6afa5743998ae468cae29d343726fb5f27b657fc8bdd66b5a4ea1de',
  'openspec-sync-specs': '6f951016a31d8400669573a1d154bb7275b71aee31e0891b1565c942b0df4a4f',
  'openspec-update-change': '06eec5a4cc52f1ec436cdde3a0207b1ceafc3f1d8c7f6cbb853f3f648c0dbbee',
};

export const openSkills = Object.keys(legacyHashes);

export async function openSkillContent(name: string) {
  return readFile(new URL(`../.agents/skills/${name}/SKILL.md`, import.meta.url), 'utf8');
}

export function isLegacyOpenSkill(name: string, bytes: Buffer) {
  return createHash('sha256').update(bytes).digest('hex') === legacyHashes[name];
}

// Skill paths must not alias another managed file, even inside the project.
export async function readManagedSkillFile(root: string, relative: string): Promise<Buffer | null> {
  const target = await assertWritablePath(root, relative);
  let part = root;
  for (const name of relative.split(path.sep)) {
    part = path.join(part, name);
    try {
      const entry = await lstat(part);
      if (entry.isSymbolicLink() || (part === target ? !entry.isFile() : !entry.isDirectory())) {
        throw new CliError('UNSAFE_PATH', `Небезопасный путь skill: ${part}`, {path: part});
      }
    } catch (error) {
      if (asError(error).code === 'ENOENT') return null;
      throw error;
    }
  }
  return readFile(target);
}

export const targetMarker = path.join('.agents', 'skills', '.openspec-target');

export async function codexTargetUpdate(openRoot: string) {
  const current = (await readManagedSkillFile(openRoot, targetMarker))?.toString('utf8') ?? '';
  if (current.split(/\r?\n/).some(line => line.trim().split(/\s+/)[0] === 'codex')) return null;
  return current + (current && !current.endsWith('\n') ? '\n' : '') + 'codex\n';
}
